   105  int dynsec_groups__process_add_role(struct dynsec__data *data, struct mosquitto_control_cmd *cmd, struct mosquitto *context)
   106  {
   107          char *groupname, *rolename;
   108          struct dynsec__group *group;
   109          struct dynsec__role *role;
   110          int priority;
   111          const char *admin_clientid, *admin_username;
   112          int rc;
   113
   114          if(json_get_string(cmd->j_command, "groupname", &groupname, false) != MOSQ_ERR_SUCCESS){
   115                  mosquitto_control_command_reply(cmd, "Invalid/missing groupname");
   116                  return MOSQ_ERR_INVAL;
   117          }
   118          if(mosquitto_validate_utf8(groupname, (int)strlen(groupname)) != MOSQ_ERR_SUCCESS){
   119                  mosquitto_control_command_reply(cmd, "Group name not valid UTF-8");
   120                  return MOSQ_ERR_INVAL;
   121          }
   122
   123          if(json_get_string(cmd->j_command, "rolename", &rolename, false) != MOSQ_ERR_SUCCESS){
   124                  mosquitto_control_command_reply(cmd, "Invalid/missing rolename");
   125                  return MOSQ_ERR_INVAL;
   126          }
   127          if(mosquitto_validate_utf8(rolename, (int)strlen(rolename)) != MOSQ_ERR_SUCCESS){
   128                  mosquitto_control_command_reply(cmd, "Role name not valid UTF-8");
   129                  return MOSQ_ERR_INVAL;
   130          }
   131          json_get_int(cmd->j_command, "priority", &priority, true, -1);
   132
   133          group = dynsec_groups__find(data, groupname);
   134          if(group == NULL){
   135                  mosquitto_control_command_reply(cmd, "Group not found");
   136                  return MOSQ_ERR_SUCCESS;
   137          }
   138
   139          role = dynsec_roles__find(data, rolename);
   140          if(role == NULL){
   141                  mosquitto_control_command_reply(cmd, "Role not found");
   142                  return MOSQ_ERR_SUCCESS;
   143          }
   144
   145          admin_clientid = mosquitto_client_id(context);
   146          admin_username = mosquitto_client_username(context);
   147
   148          rc = dynsec_rolelist__group_add(group, role, priority);
   149          if(rc == MOSQ_ERR_SUCCESS){
   150                  /* Continue */
   151          }else if(rc == MOSQ_ERR_ALREADY_EXISTS){
   152                  mosquitto_control_command_reply(cmd, "Group is already in this role");
   153                  return MOSQ_ERR_ALREADY_EXISTS;
   154          }else{
   155                  mosquitto_control_command_reply(cmd, "Internal error");
   156                  return MOSQ_ERR_UNKNOWN;
   157          }
   158
   159          mosquitto_log_printf(MOSQ_LOG_INFO, "dynsec: %s/%s | addGroupRole | groupname=%s | rolename=%s | priority=%d",
   160                          admin_clientid, admin_username, groupname, rolename, priority);
   161
   162          dynsec__config_batch_save(data);
   163          mosquitto_control_command_reply(cmd, NULL);
   164
   165          /* Enforce any changes */
   166          group__kick_all(data, group);
   167
   168          return MOSQ_ERR_SUCCESS;
   169  }
