    74  cJSON *dynsec_clientlist__all_to_json(struct dynsec__clientlist *base_clientlist)
    75  {
    76          struct dynsec__clientlist *clientlist, *clientlist_tmp;
    77          cJSON *j_clients, *j_client;
    78
    79          j_clients = cJSON_CreateArray();
    80          if(j_clients == NULL) return NULL;
    81
    82          HASH_ITER(hh, base_clientlist, clientlist, clientlist_tmp){
    83                  j_client = cJSON_CreateObject();
    84                  if(j_client == NULL){
    85                          cJSON_Delete(j_clients);
    86                          return NULL;
    87                  }
    88                  cJSON_AddItemToArray(j_clients, j_client);
    89
    90                  if(cJSON_AddStringToObject(j_client, "username", clientlist->client->username) == NULL
    91                                  || (clientlist->priority != -1 && cJSON_AddIntToObject(j_client, "priority", clientlist->priority) == NULL)
    92                                  ){
    93
    94                          cJSON_Delete(j_clients);
    95                          return NULL;
    96                  }
    97          }
    98          return j_clients;
    99  }
