   102  int dynsec_clientlist__add(struct dynsec__clientlist **base_clientlist, struct dynsec__client *client, int priority)
   103  {
   104          struct dynsec__clientlist *clientlist;
   105
   106          HASH_FIND(hh, *base_clientlist, client->username, strlen(client->username), clientlist);
   107          if(clientlist != NULL){
   108                  /* Client is already in the group */
   109                  return MOSQ_ERR_SUCCESS;
   110          }
   111
   112          clientlist = mosquitto_malloc(sizeof(struct dynsec__clientlist));
   113          if(clientlist == NULL){
   114                  return MOSQ_ERR_NOMEM;
   115          }
   116
   117          clientlist->client = client;
   118          clientlist->priority = priority;
   119          HASH_ADD_KEYPTR_INORDER(hh, *base_clientlist, client->username, strlen(client->username), clientlist, dynsec_clientlist__cmp);
   120
   121          return MOSQ_ERR_SUCCESS;
   122  }
