    44  int mosquitto_plugin_init(mosquitto_plugin_id_t *identifier, void **user_data, struct mosquitto_opt *options, int option_count)
    45  {
    46          int i;
    47          int rc;
    48
    49          UNUSED(user_data);
    50
    51          memset(&dynsec_data, 0, sizeof(struct dynsec__data));
    52
    53          for(i=0; i<option_count; i++){
    54                  if(!strcasecmp(options[i].key, "config_file")){
    55                          dynsec_data.config_file = mosquitto_strdup(options[i].value);
    56                          if(dynsec_data.config_file == NULL){
    57                                  return MOSQ_ERR_NOMEM;
    58                          }
    59                  }else if(!strcasecmp(options[i].key, "password_init_file")){
    60                          dynsec_data.password_init_file = mosquitto_strdup(options[i].value);
    61                          if(dynsec_data.password_init_file == NULL){
    62                                  return MOSQ_ERR_NOMEM;
    63                          }
    64                  }
    65          }
    66          if(dynsec_data.config_file == NULL){
    67                  mosquitto_log_printf(MOSQ_LOG_WARNING, "Warning: Dynamic security plugin has no plugin_opt_config_file defined. The plugin will not be activated.");
    68                  return MOSQ_ERR_SUCCESS;
    69          }
    70
    71          plg_id = identifier;
    72          mosquitto_plugin_set_info(identifier, "dynamic-security", NULL);
    73
    74          dynsec__config_load(&dynsec_data);
    75
    76          rc = mosquitto_callback_register(plg_id, MOSQ_EVT_CONTROL, dynsec_control_callback, "$CONTROL/dynamic-security/v1", &dynsec_data);
    77          if(rc == MOSQ_ERR_ALREADY_EXISTS){
    78                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Dynamic security plugin can currently only be loaded once.");
    79                  mosquitto_log_printf(MOSQ_LOG_ERR, "Note that this was previously incorrectly allowed but could cause problems with duplicate entries in the config.");
    80                  goto error;
    81          }else if(rc == MOSQ_ERR_NOMEM){
    82                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Out of memory.");
    83                  goto error;
    84          }else if(rc != MOSQ_ERR_SUCCESS){
    85                  goto error;
    86          }
    87
    88          rc = mosquitto_callback_register(plg_id, MOSQ_EVT_BASIC_AUTH, dynsec_auth__basic_auth_callback, NULL, &dynsec_data);
    89          if(rc == MOSQ_ERR_ALREADY_EXISTS){
    90                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Dynamic security plugin can only be loaded once.");
    91                  goto error;
    92          }else if(rc == MOSQ_ERR_NOMEM){
    93                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Out of memory.");
    94                  goto error;
    95          }else if(rc != MOSQ_ERR_SUCCESS){
    96                  goto error;
    97          }
    98
    99          rc = mosquitto_callback_register(plg_id, MOSQ_EVT_ACL_CHECK, dynsec__acl_check_callback, NULL, &dynsec_data);
   100          if(rc == MOSQ_ERR_ALREADY_EXISTS){
   101                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Dynamic security plugin can only be loaded once.");
   102                  goto error;
   103          }else if(rc == MOSQ_ERR_NOMEM){
   104                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Out of memory.");
   105                  goto error;
   106          }else if(rc != MOSQ_ERR_SUCCESS){
   107                  goto error;
   108          }
   109
   110          rc = mosquitto_callback_register(plg_id, MOSQ_EVT_TICK, dynsec__tick_callback, NULL, &dynsec_data);
   111          if(rc == MOSQ_ERR_NOMEM){
   112                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Out of memory.");
   113                  goto error;
   114          }else if(rc != MOSQ_ERR_SUCCESS){
   115                  goto error;
   116          }
   117
   118          return MOSQ_ERR_SUCCESS;
   119  error:
   120          mosquitto_free(dynsec_data.config_file);
   121          dynsec_data.config_file = NULL;
   122          return rc;
   123  }
